import "fmt"

type Account struct{ balance, floor int64 }

func (a *Account) Withdraw(amount int64) error {
	if amount <= 0 {
		return fmt.Errorf("withdrawal amount %d must be positive", amount)
	}
	nextBalance := a.balance - amount
	if nextBalance < a.floor {
		return fmt.Errorf("insufficient balance: %d < floor %d", nextBalance, a.floor)
	}
	a.balance = nextBalance
	if a.balance < a.floor {
		panic(fmt.Sprintf("invariant broken: balance %d < floor %d", a.balance, a.floor))
	}
	return nil
}
